// Bounded fictional CMS DOM/Ant-shaped widgets. No employer implementation or
// external network is loaded. Metadata matches the read-only actual six-field set.
import {readFile} from 'node:fs/promises';
const replace=(source,before,after)=>{if(source.split(before).length!==2)throw Error('fixture_anchor_not_unique');return source.replace(before,after);};
export async function internshipFixture(){
  const html=await readFile('tests/fixtures/cms-ant-v3-date-synthetic.html','utf8');
  let date=html.match(/<script>([\s\S]*?)<\/script>/u)[1].trim().replace(/\r\n/gu,'\n');
  date=date.replace(/^\(\(\) => \{/u,'function installDate(rowIndex) {').replace(/\}\)\(\);$/u,'}');
  date=date.replace(/const hosts = \{[\s\S]*?\n    \};/u,"const hosts={start:document.getElementById('date-start-'+rowIndex),end:document.getElementById('date-end-'+rowIndex)};");
  date=date.replaceAll("state[current].value = date;","state[current].value = date;commit(rowIndex,current==='start'?49170508:49170510,date);");
  date=date.replaceAll("'fictional-resume-form'","'fixture-form'").replaceAll("'site-save'","'save'");
  date=replace(date,'window.syntheticCmsDate = {','window.fixtureDates[rowIndex] = {');
  return `<!doctype html><meta charset="utf-8"><title>Fictional CMS internship acceptance</title><style>
body{font:15px sans-serif;margin:20px}.form-cell{border:1px solid;padding:10px}.form-cell-inner{border-bottom:1px solid #aaa;padding:6px}.ant-form-item{display:flex;margin:8px;gap:15px}.ant-form-item-label{width:140px}.ant-select-selection{display:inline-block;min-width:130px;min-height:24px;border:1px solid}.ant-select{display:inline-block;margin-right:10px}.ant-select-dropdown{background:white;border:1px solid;position:relative;z-index:20}.ant-calendar-picker-container{position:fixed;top:30px;left:240px;background:white;border:1px solid;z-index:40;padding:8px}.ant-calendar-body{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}.ant-calendar-header{display:flex}.ant-calendar-year-panel .ant-calendar-body,.ant-calendar-month-panel .ant-calendar-body{grid-template-columns:repeat(4,1fr)}.add-more{padding:12px;cursor:pointer}</style>
<form id="fixture-form"><section id="14" class="form-cell"><div class="tit-wrap"><div class="tit">教育经历必填</div></div><input id="outside-education" value="original education preserved"></section><input id="unrelated" value="original other value"><section id="49170501" class="form-cell"><div class="tit-wrap"><div class="tit">实习经历</div></div><div class="form-cell-right"></div></section><button id="save" type="button">保存</button><button type="submit">提交申请</button></form><script>
window.fixtureCounts={adds:0,saves:0,submits:0,textEvents:0,selects:0};window.fixtureDates=[];window.fixtureBeforeWrite=null;
const definitions=[{oldItemId:49170508,name:'开始时间',fillType:2},{oldItemId:49170510,name:'结束时间',fillType:2},{oldItemId:49170514,name:'企业名称',fillType:1},{oldItemId:49170517,name:'工作性质',fillType:4,dataSourceMap:{'0/461/578':'全职','0/461/580':'实习'}},{oldItemId:49170519,name:'职位名称',fillType:1},{oldItemId:49170523,name:'工作描述',fillType:6}];
window.fixtureProps={id:49170501,infoData:[],isMutiRecord:0,rowSize:10000,formData:{}};
const section=document.getElementById('49170501');section.__reactFiber$offline={memoizedProps:window.fixtureProps,return:null};
function commit(row,id,value){window.fixtureProps.formData['49170501_'+id+'_'+(row+1)]=value;}
${date}
function mountSelect(item,meta,index){const select=document.createElement('div');select.className='ant-select';const selection=document.createElement('div');selection.className='ant-select-selection ant-select-selection--single';selection.tabIndex=0;selection.setAttribute('role','combobox');selection.setAttribute('aria-controls','options-'+index+'-'+meta.oldItemId);const display=document.createElement('span');display.className='ant-select-selection-selected-value';selection.append(display);select.append(selection);item.append(select);selection.addEventListener('click',()=>{select.classList.add('ant-select-open');const menu=document.createElement('div');menu.className='ant-select-dropdown';const list=document.createElement('ul');list.className='ant-select-dropdown-menu';list.id=selection.getAttribute('aria-controls');list.setAttribute('role','listbox');for(const [code,text]of Object.entries(meta.dataSourceMap)){const li=document.createElement('li');li.className='ant-select-dropdown-menu-item';li.setAttribute('role','option');li.textContent=text;li.addEventListener('click',()=>{window.fixtureCounts.selects++;display.textContent=text;commit(index,meta.oldItemId,code);menu.remove();select.classList.remove('ant-select-open');});list.append(li);}menu.append(list);document.body.append(menu);});}
function addRow(){const index=window.fixtureProps.infoData.length,row=document.createElement('div');row.className='form-cell-inner';window.fixtureProps.infoData.push(definitions.map(meta=>({...meta,isNeed:1,itemId:'49170501_'+meta.oldItemId,uniqueId:'row-'+index+'-'+meta.oldItemId})));for(const meta of definitions){const wrap=document.createElement('div');wrap.id='49170501_'+meta.oldItemId+'_'+index;const item=document.createElement('div');item.className='ant-form-item';wrap.append(item);const label=document.createElement('div');label.className='ant-form-item-label';label.innerHTML='<label>'+meta.name+'</label>';item.append(label);row.append(wrap);if(meta.fillType===2){const host=document.createElement('div');host.id='date-'+(meta.oldItemId===49170508?'start':'end')+'-'+index;item.append(host);}else if(meta.fillType===4)mountSelect(item,meta,index);else{const input=document.createElement(meta.fillType===6?'textarea':'input');input.addEventListener('input',()=>{window.fixtureCounts.textEvents++;commit(index,meta.oldItemId,input.value)});input.addEventListener('change',()=>commit(index,meta.oldItemId,input.value));item.append(input);}}const right=section.querySelector('.form-cell-right');right.insertBefore(row,right.querySelector('.add-more'));installDate(index);}
const add=document.createElement('div');add.className='add-more';add.textContent='添加新的实习经历';add.addEventListener('click',()=>{window.fixtureCounts.adds++;addRow()});section.querySelector('.form-cell-right').append(add);addRow();document.getElementById('save').addEventListener('click',()=>window.fixtureCounts.saves++);document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();window.fixtureCounts.submits++});
window.fixtureSeed=(source)=>{const row=0;fixtureDates[row].setExisting('start',source.startDate);fixtureDates[row].setExisting('end',source.endDate);commit(row,49170508,source.startDate);commit(row,49170510,source.endDate);for(const [id,key]of [[49170514,'organization'],[49170519,'position'],[49170523,'description']]){const input=document.getElementById('49170501_'+id+'_0').querySelector('input,textarea');input.value=source[key];commit(row,id,source[key]);}document.getElementById('49170501_49170517_0').querySelector('.ant-select-selection-selected-value').textContent='实习';commit(0,49170517,'0/461/580');};
window.fixtureSnapshot=()=>({counts:{...fixtureCounts},records:fixtureProps.infoData.length,formData:structuredClone(fixtureProps.formData),dates:fixtureDates.map(x=>x.snapshot()),outside:document.getElementById('unrelated').value,education:document.getElementById('outside-education').value});
</script>`;
}
